WITH remaining_keys AS (SELECT id, product_id FROM order_items EXCEPT ALL SELECT id, product_id FROM order_items WHERE unit_price <= 210), verified AS (SELECT s.* FROM order_items s INNER JOIN remaining_keys k ON s.id = k.id AND s.product_id = k.product_id) SELECT order_id, PERCENTILE_APPROX(quantity, ARRAY(0.25, 0.5, 0.75)) AS quantity_quartiles, COUNT(DISTINCT product_id) AS distinct_product_ids FROM verified GROUP BY 1 ORDER BY order_id NULLS LAST;
